-- =============================================================================
-- 454 — LE CAHIER D'EXERCICES DE TLE (partie 19)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 454 --niveau Tle --matieres biochimie-biologie-biotechnologie,spcl --suffixe 19 > supabase/contenu/454_exercices_tle_19.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   biochimie-biologie-biotechnologie.k140  24 exercices · 8 chapitres
--   biochimie-biologie-biotechnologie.k141  24 exercices · 8 chapitres
--   spcl.k196               24 exercices · 8 chapitres
--   spcl.k197               24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('909b428e-56d4-5fee-a203-ad88d20f1681'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les notes de Samia","competence":"lire-tableau","situation":"Samia a passé l’écrit et l’épreuve pratique de la spécialité biotechnologies. Le tableau donne le poids de chaque partie et ses deux notes sur 20.","documents":[{"id":"notes","type":"tableau","titre":"La spécialité de Samia","colonnes":["Partie","Durée","Coefficient","Note /20"],"lignes":[["Écrite","3 h","7","12"],["Pratique (ECE)","3 h","9","14"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le coefficient de la partie qui pèse le plus dans la spécialité.","aide":"Compare les deux coefficients de la colonne du milieu.","type":"zone","document":"notes","multiple":false},{"enonce":"Quel est le total des coefficients de la spécialité ?","aide":"Additionne les deux coefficients du tableau.","type":"nombre"},{"enonce":"Calcule la note de spécialité de Samia : (12 × 7 + 14 × 9) ÷ 16. Arrondis au dixième.","aide":"Multiplie chaque note par son coefficient, additionne, puis divise par 16.","type":"nombre","unite":"/20"},{"enonce":"Pourquoi sa note de spécialité est-elle plus proche de 14 que de 12 ?","aide":"Regarde comment le coefficient agit sur la moyenne.","type":"choix","options":[{"id":"a","texte":"Les deux notes ont le même coefficient, donc la moyenne tombe exactement entre les deux"},{"id":"b","texte":"La pratique dure plus longtemps que l’écrit, donc elle compte davantage dans le total"},{"id":"c","texte":"La moyenne est toujours arrondie vers la note la plus haute des deux épreuves passées"},{"id":"d","texte":"Le coefficient de la pratique est plus grand, donc sa note pèse davantage dans la moyenne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"L’épreuve pratique a le coefficient **9**, contre 7 pour l’écrit."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"7 + 9 = **16**."},{"cle":{"type":"nombre","valeur":13.1,"tolerance":0.05},"affichage":"13,1 /20","explication":"(84 + 126) ÷ 16 = 210 ÷ 16 = 13,125, soit **13,1** sur 20."},{"cle":{"type":"choix","ids":["d"]},"explication":"Dans une moyenne pondérée, la note au **coefficient le plus fort** attire le résultat. Ici la pratique (9) l’emporte sur l’écrit (7) ; les durées sont pourtant égales (3 h)."}]$ex$::jsonb),
  ('909b428e-56d4-5fee-a203-ad88d20f1681'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois heures, pas une minute de plus","competence":"resoudre","situation":"En ECE, tu disposes de 3 h pour tout faire. Yanis compare deux façons de s’organiser pour un dosage avec une incubation pendant laquelle il n’a rien à surveiller.","documents":[{"id":"plan","type":"tableau","titre":"Les étapes du sujet de Yanis","colonnes":["Étape","Durée (min)","Présent à la paillasse ?"],"lignes":[["Préparer le milieu et les échantillons","20","Oui"],["Incubation","40","Non"],["Calculs de préparation (dilutions)","25","Oui"],["Mesure","15","Oui"],["Rangement et déchets","10","Oui"]],"enteteLignes":true,"source":"Durées inventées pour l’exercice"}],"questions":[{"enonce":"Touche l’étape pendant laquelle Yanis peut faire autre chose.","aide":"Regarde la dernière colonne : cherche l’étape sans présence obligatoire.","type":"zone","document":"plan","multiple":false},{"enonce":"Yanis enchaîne toutes les étapes l’une après l’autre. Quelle est la durée totale, en minutes ?","aide":"Additionne les cinq durées de la colonne du milieu.","type":"nombre","unite":"min"},{"enonce":"Il lance l’incubation et fait ses calculs de préparation pendant l’attente. Quelle est alors la durée totale, en minutes ?","aide":"Les 25 min de calculs se passent à l’intérieur des 40 min d’incubation : elles ne s’ajoutent plus.","type":"nombre","unite":"min"},{"enonce":"Quelle est la meilleure règle d’organisation à retenir pour l’ECE ?","aide":"Pense à ce qui se passe pendant que l’incubation tourne toute seule.","type":"choix","options":[{"id":"a","texte":"Faire les étapes les plus courtes en premier pour avancer vite dans le sujet"},{"id":"b","texte":"Ranger la paillasse d’abord pour pouvoir travailler ensuite dans de bonnes conditions"},{"id":"c","texte":"Lancer d’abord l’étape qui demande du temps, puis travailler pendant l’attente"},{"id":"d","texte":"Attendre la fin de l’incubation avant de commencer à lire le reste du sujet"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Pendant l’**incubation**, rien ne demande sa présence : c’est le moment de faire les calculs de préparation."},{"cle":{"type":"nombre","valeur":110,"tolerance":0},"affichage":"110 min","explication":"20 + 40 + 25 + 15 + 10 = **110 min**."},{"cle":{"type":"nombre","valeur":85,"tolerance":0},"affichage":"85 min","explication":"20 + 40 + 15 + 10 = **85 min** : il gagne 25 min."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Lancer en premier ce qui demande du temps** (incubation, cinétique) : on peut alors avancer sur les calculs pendant l’attente."}]$ex$::jsonb),
  ('909b428e-56d4-5fee-a203-ad88d20f1681'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La grille de l’examinateur","competence":"analyser-document","situation":"Léa sort de son ECE. Elle a noté ce qu’elle a fait dans son carnet, et l’examinateur a rempli une grille sur 20. Croise les deux documents pour comprendre où elle a perdu des points.","documents":[{"id":"carnet","type":"texte","genre":"consigne","titre":"Le carnet de Léa","blocs":["Léa a lancé sa cinétique en premier, puis a préparé ses dilutions pendant l’attente. Elle a manipulé la culture sans ses lunettes, a placé un témoin dans chaque série, puis a noté dans son compte rendu : concentration = 0,45."],"source":"Texte écrit pour l’exercice"},{"id":"grille","type":"tableau","titre":"La grille de l’examinateur","colonnes":["Compétence","Barème","Points de Léa"],"lignes":[["Prévention des risques","4","1"],["Réalisation en autonomie","6","6"],["Résultat et métrologie","5","3"],["Interprétation","5","4"]],"enteteLignes":true,"source":"Barème inventé pour l’exercice"}],"questions":[{"enonce":"Touche l’équipement de protection que Léa a oublié de porter.","aide":"Cherche l’objet qui protège les yeux.","type":"zone","document":"carnet","multiple":false},{"enonce":"Touche le résultat que Léa a écrit sans son unité.","aide":"Un résultat sans unité est incomplet : cherche le nombre seul.","type":"zone","document":"carnet","multiple":true},{"enonce":"Touche la compétence où Léa perd le plus de points.","aide":"Pour chaque ligne, calcule barème − points de Léa.","type":"zone","document":"grille","multiple":false},{"enonce":"Quelle est la note de Léa à la grille, sur 20 ?","aide":"Additionne la dernière colonne.","type":"nombre","unite":"/20"},{"enonce":"Quel conseil l’aiderait le plus pour son prochain ECE ?","aide":"Reprends les deux oublis repérés dans son carnet.","type":"choix","options":[{"id":"a","texte":"Travailler moins vite pour éviter toute erreur et vérifier chaque geste deux fois de suite"},{"id":"b","texte":"Ne noter les résultats qu’à la fin pour ne pas perdre de temps pendant les manipulations"},{"id":"c","texte":"Annoncer ses mesures de prévention avant d’agir, puis écrire chaque résultat avec son unité"},{"id":"d","texte":"Supprimer le témoin pour gagner du temps et se concentrer sur la mesure principale"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"Les **lunettes** : la prévention s’annonce et se met en place avant de manipuler."},{"cle":{"type":"zone","ids":["m38","m39"]},"explication":"**0,45** n’a pas d’unité (ni d’incertitude) : il lui manque sa dimension métrologique."},{"cle":{"type":"zone","ids":["r0c0"]},"explication":"Prévention : 4 − 1 = **3 points perdus**, contre 0, 2 et 1 pour les autres. Cela colle avec les lunettes oubliées."},{"cle":{"type":"nombre","valeur":14,"tolerance":0},"affichage":"14 /20","explication":"1 + 6 + 3 + 4 = **14** sur 20."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les deux points perdus viennent de la **prévention** et de l’**unité** : on les annonce et on les note dès le départ. Le témoin, lui, est indispensable."}]$ex$::jsonb),
  ('db450763-6653-5ad5-bbf3-40a5d0ae5fde'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le coup de pouce de l’ATP","competence":"lire-tableau","situation":"La synthèse de la glutamine est une étape d’anabolisme. Le tableau donne l’enthalpie libre standard de trois réactions.","documents":[{"id":"dg","type":"tableau","titre":"Enthalpies libres standard","colonnes":["Réaction","ΔrG’° (kJ·mol⁻¹)"],"lignes":[["Glutamate + NH₄⁺ → glutamine","+14,2"],["ATP + H₂O → ADP + Pi","−30,5"],["Glucose-6-phosphate + H₂O → glucose + Pi","−13,8"]],"enteteLignes":true,"source":"Valeurs arrondies, conditions standard biologiques"}],"questions":[{"enonce":"Touche la valeur de la réaction endergonique.","aide":"Une réaction endergonique a un ΔrG’° positif.","type":"zone","document":"dg","multiple":false},{"enonce":"On couple la synthèse de la glutamine à l’hydrolyse de l’ATP. Quel est le ΔrG’° de la réaction couplée, en kJ·mol⁻¹ ?","aide":"Additionne les deux ΔrG’° en gardant leur signe.","type":"nombre","unite":"kJ·mol⁻¹"},{"enonce":"Que dire de la réaction couplée ?","aide":"Regarde le signe de la somme.","type":"choix","options":[{"id":"a","texte":"Elle est impossible, car il faut toujours deux ΔrG’° de même signe"},{"id":"b","texte":"Elle reste impossible, car l’un des deux ΔrG’° est positif au départ"},{"id":"c","texte":"Elle est spontanée, car l’ATP est consommé sans rien produire à la fin"},{"id":"d","texte":"Elle est spontanée, car la somme des deux ΔrG’° est négative"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Seule la synthèse de la glutamine a un ΔrG’° **positif** (+14,2) : elle est endergonique, impossible seule."},{"cle":{"type":"nombre","valeur":-16.3,"tolerance":0.05},"affichage":"−16,3 kJ·mol⁻¹","explication":"+14,2 + (−30,5) = **−16,3 kJ·mol⁻¹**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La somme est négative : la réaction couplée est **spontanée**. L’ATP « paie » l’endergonique."}]$ex$::jsonb),
  ('db450763-6653-5ad5-bbf3-40a5d0ae5fde'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui donne ses électrons à qui ?","competence":"calculer","situation":"Les couples d’oxydoréduction du métabolisme se classent par potentiel standard apparent E’°. Les électrons vont spontanément du E’° le plus bas vers le E’° le plus haut. On prend F = 96 500 C·mol⁻¹ et n = 2.","documents":[{"id":"eo","type":"tableau","titre":"Potentiels standard apparents","colonnes":["Couple","E’° (V)"],"lignes":[["NAD⁺ / NADH","−0,32"],["FAD / FADH₂ (libre)","−0,22"],["Pyruvate / lactate","−0,19"],["O₂ / H₂O","+0,82"]],"enteteLignes":true,"source":"Valeurs arrondies à pH 7"}],"questions":[{"enonce":"Touche le couple qui est le meilleur accepteur d’électrons.","aide":"Le meilleur accepteur a le E’° le plus haut.","type":"zone","document":"eo","multiple":false},{"enonce":"Range ces couples dans l’ordre des E’° croissants : du meilleur donneur au meilleur accepteur.","aide":"Compare les nombres : −0,32 est plus petit que −0,22.","type":"ordre","items":[{"id":"a","texte":"NAD⁺ / NADH"},{"id":"b","texte":"Pyruvate / lactate"},{"id":"c","texte":"FAD / FADH₂"},{"id":"d","texte":"O₂ / H₂O"}]},{"enonce":"Le NADH réduit le pyruvate en lactate (ΔE’° = +0,13 V). Calcule ΔrG’° = −n × F × ΔE’°, en kJ·mol⁻¹, arrondi au dixième.","aide":"Convertis les joules en kilojoules : −2 × 96 500 × 0,13 = … J.","type":"nombre","unite":"kJ·mol⁻¹"},{"enonce":"Le NADH cède ses électrons au dioxygène. ΔE’° = 0,82 − (−0,32). Calcule ΔrG’°, en kJ·mol⁻¹ arrondi à l’unité.","aide":"Commence par ΔE’° = 1,14 V.","type":"nombre","unite":"kJ·mol⁻¹"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le couple **O₂ / H₂O** (+0,82 V) est le plus haut : c’est l’accepteur final de la respiration."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"Du plus bas au plus haut : −0,32 < −0,22 < −0,19 < +0,82."},{"cle":{"type":"nombre","valeur":-25.1,"tolerance":0.2},"affichage":"−25,1 kJ·mol⁻¹","explication":"−2 × 96 500 × 0,13 = −25 090 J ≈ **−25,1 kJ·mol⁻¹** : spontanée."},{"cle":{"type":"nombre","valeur":-220,"tolerance":1},"affichage":"−220 kJ·mol⁻¹","explication":"−2 × 96 500 × 1,14 ≈ −220 000 J = **−220 kJ·mol⁻¹** : bien plus exergonique que le pyruvate."}]$ex$::jsonb),
  ('db450763-6653-5ad5-bbf3-40a5d0ae5fde'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Combien d’énergie récupère-t-on ?","competence":"modeliser","situation":"Un même glucose peut être oxydé par respiration ou par fermentation lactique. On compare l’énergie libérée et l’ATP fabriqué. L’énergie stockée par l’ATP se calcule à 30,5 kJ par mole d’ATP.","documents":[{"id":"bilan","type":"tableau","titre":"Bilans pour une mole de glucose","colonnes":["Voie","Énergie libérée (kJ)","ATP formés (mol)"],"lignes":[["Respiration","2840","30"],["Fermentation lactique","196","2"]],"enteteLignes":true,"source":"Valeurs arrondies de manuels"},{"id":"g","type":"graphique","forme":"barres","titre":"Énergie libérée par mole de glucose","categories":["Respiration","Fermentation lactique"],"series":[{"nom":"Énergie libérée","valeurs":[2840,196],"teinte":"turquoise"}],"axeY":{"titre":"Énergie libérée","unite":"kJ","min":0,"max":3000,"pas":500},"axeX":{"titre":"Voie métabolique"},"valeurs":false}],"questions":[{"enonce":"Touche la voie qui libère le plus d’énergie par glucose.","aide":"Cherche la barre la plus haute.","type":"zone","document":"g","multiple":false},{"enonce":"Quelle énergie est stockée dans l’ATP par la respiration (30 mol d’ATP × 30,5 kJ·mol⁻¹), en kJ ?","aide":"Multiplie le nombre de moles d’ATP par 30,5.","type":"nombre","unite":"kJ"},{"enonce":"Quel est le rendement de la respiration : énergie stockée ÷ énergie libérée ? Donne un pourcentage arrondi à l’unité.","aide":"Divise 915 par 2 840, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Même calcul pour la fermentation lactique (2 mol d’ATP × 30,5 kJ·mol⁻¹ sur 196 kJ). Pourcentage arrondi à l’unité.","aide":"Énergie stockée : 2 × 30,5 = 61 kJ.","type":"nombre","unite":"%"},{"enonce":"Que conclure de la comparaison ?","aide":"Compare les deux pourcentages, puis les deux énergies libérées.","type":"choix","options":[{"id":"a","texte":"La respiration a un rendement deux fois plus grand, car elle fabrique trente fois plus d’ATP"},{"id":"b","texte":"Les deux voies libèrent la même énergie, mais la respiration en stocke beaucoup plus"},{"id":"c","texte":"Les rendements sont voisins ; la respiration rapporte bien plus d’ATP car elle libère bien plus d’énergie"},{"id":"d","texte":"La fermentation a un bien meilleur rendement, car elle produit le moins de déchets à la fin"}],"multiple":false}]}$ex$::jsonb,
