  ('58cd43b9-deac-5cc7-aab6-0a4a2b184a54'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Dans la mitochondrie","competence":"observer-schema","situation":"Chez un eucaryote, l’oxydation du glucose commence hors de la mitochondrie et s’achève à l’intérieur. Le schéma montre une mitochondrie en coupe, avec trois repères lettrés.","documents":[{"id":"mito","type":"schema","titre":"Une mitochondrie en coupe (schéma simplifié)","largeur":360,"hauteur":225,"elements":[{"forme":"ellipse","cx":190,"cy":105,"rx":140,"ry":80,"teinte":"encre","motif":"clair"},{"forme":"ellipse","cx":190,"cy":105,"rx":112,"ry":52,"teinte":"encre","motif":"clair"},{"forme":"cercle","cx":190,"cy":105,"r":11,"texte":"A","teinte":"encre","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":190,"cy":40,"r":11,"texte":"B","teinte":"encre","motif":"clair","id":"z2","zone":true},{"forme":"cercle","cx":24,"cy":105,"r":11,"texte":"C","teinte":"encre","motif":"clair","id":"z3","zone":true},{"forme":"texte","x":190,"y":205,"texte":"Mitochondrie (coupe)","taille":"petit","ancre":"milieu","italique":true}]}],"questions":[{"enonce":"Touche la lettre qui marque le lieu du cycle de Krebs.","aide":"Le cycle de Krebs se déroule dans la matrice, à l’intérieur de la membrane interne.","type":"zone","document":"mito","multiple":false},{"enonce":"Touche la lettre qui marque l’espace où s’accumulent les protons pompés par la chaîne respiratoire.","aide":"Cet espace est pris entre les deux membranes.","type":"zone","document":"mito","multiple":false},{"enonce":"Touche la lettre qui marque le lieu de la glycolyse.","aide":"La glycolyse se passe hors de la mitochondrie.","type":"zone","document":"mito","multiple":false},{"enonce":"Pourquoi les protons refluent-ils vers la matrice par l’ATP synthase ?","aide":"Un gradient est une réserve d’énergie qu’on libère en le laissant se vider.","type":"choix","options":[{"id":"a","texte":"Ils suivent leur gradient et cette descente fournit l’énergie qui fabrique l’ATP"},{"id":"b","texte":"Ils sont attirés par le dioxygène, qui les consomme pour fabriquer de l’ATP directement"},{"id":"c","texte":"Ils sont chassés par le cycle de Krebs, qui les libère en grande quantité dans la matrice"},{"id":"d","texte":"Ils repartent vers la matrice pour y être transformés en CO₂ par l’ATP synthase"}],"multiple":false}]}$ex$::jsonb,
