  ('151b3b5f-5aa0-5587-acdf-27aedaa1051f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La courbe de fusion d’un ADN","competence":"lire-graphique","situation":"On chauffe lentement une solution d’ADN double brin et on mesure son absorbance à 260 nm à chaque palier de température.","documents":[{"id":"fusion","type":"graphique","forme":"courbe","titre":"Absorbance de l’ADN à 260 nm en fonction de la température","categories":["60","65","70","75","80","85","90","95","100"],"series":[{"nom":"A260","valeurs":[0.5,0.5,0.51,0.55,0.64,0.75,0.88,0.97,1],"teinte":"turquoise"}],"axeY":{"titre":"Absorbance à 260 nm","min":0,"max":1.2,"pas":0.2},"axeX":{"titre":"Température (°C)"},"valeurs":false,"source":"Mesures idéalisées"}],"questions":[{"enonce":"Touche le point de la température de fusion Tm : celui où l’absorbance est à mi-chemin entre son minimum (0,50) et son maximum (1,00).","aide":"À mi-chemin entre 0,50 et 1,00, l’absorbance vaut 0,75.","type":"zone","document":"fusion","multiple":false},{"enonce":"De quel pourcentage l’absorbance a-t-elle augmenté entre 60 °C et 100 °C ?","aide":"Calcule l’écart entre les deux valeurs, puis divise-le par la valeur de départ.","type":"nombre","unite":"%"},{"enonce":"On chauffe de la même façon un second ADN, plus riche en C et G. Où se place sa courbe par rapport à celle du document ?","aide":"Compte les liaisons hydrogène d’une paire C≡G et d’une paire A=T.","type":"choix","options":[{"id":"a","texte":"Décalée vers les températures plus basses, car les paires C≡G n’ont que deux liaisons hydrogène à rompre"},{"id":"b","texte":"Décalée vers les températures plus hautes, car ce sont les liaisons phosphodiester qui se rompent plus tard"},{"id":"c","texte":"Identique, car la température de fusion dépend de la longueur de l’ADN et non de ses bases"},{"id":"d","texte":"Décalée vers les températures plus hautes, car les paires C≡G ont trois liaisons hydrogène à rompre"}],"multiple":false}]}$ex$::jsonb,
