   $ex${"titre":"Lire le profil d’une micro-galerie","competence":"modeliser","situation":"Une micro-galerie comporte six tests, lus par groupes de trois. Dans chaque groupe, un test positif vaut 1, 2 ou 4, selon sa place ; on additionne les valeurs des tests positifs pour obtenir un chiffre.","documents":[{"id":"galerie","type":"tableau","titre":"Lecture de la galerie","colonnes":["Test","Valeur si positif","Résultat"],"lignes":[["Test 1","1","+"],["Test 2","2","−"],["Test 3","4","+"],["Test 4","1","−"],["Test 5","2","+"],["Test 6","4","+"]],"enteteLignes":true},{"id":"catalogue","type":"tableau","titre":"Extrait du catalogue d’identification","colonnes":["Profil","Espèce","Identification"],"lignes":[["54","Espèce X","70 %"],["56","Espèce Y","96 %"],["16","Espèce Z","91 %"]],"enteteLignes":true,"source":"Noms d’espèces fictifs"}],"questions":[{"enonce":"Écris le profil numérique de la souche.","aide":"Additionne seulement les valeurs des tests positifs, groupe par groupe.","type":"trous","segments":["Le premier chiffre est ",0," et le second chiffre est ",1,"."]},{"enonce":"Quelle espèce le catalogue propose-t-il pour ce profil ?","aide":"Cherche la ligne dont le profil est exactement celui que tu as calculé.","type":"choix","options":[{"id":"a","texte":"L’espèce X, avec une identification de 70 %, car son profil est le plus proche"},{"id":"b","texte":"L’espèce Y, avec une identification de 96 %"},{"id":"c","texte":"Aucune espèce : le catalogue ne donne rien pour un profil à deux chiffres"},{"id":"d","texte":"L’espèce Z, avec une identification de 91 %, car elle est la plus fréquente"}],"multiple":false},{"enonce":"Le test 5 est lu négatif par erreur. Quel serait alors le profil complet ?","aide":"Le second chiffre perd la valeur du test 5.","type":"nombre"},{"enonce":"Le témoin négatif de la galerie donne un test positif. Que faut-il faire ?","aide":"Un témoin négatif ne doit jamais réagir.","type":"choix","options":[{"id":"a","texte":"Compter ce test comme négatif pour la souche, car le témoin a déjà réagi pour elle"},{"id":"b","texte":"Garder le profil obtenu, car seuls les tests de l’échantillon comptent dans la lecture de la galerie"},{"id":"c","texte":"Considérer la galerie comme invalide et la recommencer, car un réactif ou une manipulation est en cause"},{"id":"d","texte":"Retirer ce test du profil et identifier la souche avec les cinq tests restants de la galerie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["5"],["6"]]},"affichage":"5 · 6","explication":"Groupe 1 : tests 1 et 3 positifs, 1 + 4 = **5**. Groupe 2 : tests 5 et 6 positifs, 2 + 4 = **6**. Profil : 56."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le profil 56 correspond à l’**espèce Y** (96 %)."},{"cle":{"type":"nombre","valeur":54,"tolerance":0},"affichage":"54","explication":"Second groupe : seul le test 6 est positif, il reste 4. Le profil devient **54**, qui mène à l’espèce X à 70 % : une erreur de lecture change l’espèce proposée."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un témoin négatif qui réagit signale une **réaction parasite** : la galerie n’a aucune valeur et doit être refaite."}]$ex$::jsonb),
  ('4c522328-b9f4-5090-93d1-4e4172fdd5d8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les étapes d’un ELISA sandwich","competence":"observer-schema","situation":"Un ELISA sandwich détecte un antigène dans un échantillon. Le schéma résume la procédure dans un puits de microplaque.","documents":[{"id":"elisa","type":"chaine","disposition":"colonne","titre":"Un ELISA sandwich","noeuds":[{"id":"z1","texte":"Anticorps de capture fixé au fond du puits"},{"id":"z2","texte":"Antigène de l’échantillon fixé, puis lavage"},{"id":"z3","texte":"Anticorps conjugué à une enzyme, puis lavage"},{"id":"z4","texte":"Substrat chromogène ajouté"},{"id":"z5","texte":"Couleur proportionnelle à la quantité d’antigène"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche l’étape où l’on ajoute la molécule qui porte l’enzyme.","aide":"L’enzyme est couplée à un second anticorps.","type":"zone","document":"elisa","multiple":false},{"enonce":"Touche l’étape où l’on ajoute la molécule que l’enzyme transforme en produit coloré.","aide":"Cette molécule se nomme « substrat chromogène ».","type":"zone","document":"elisa","multiple":false},{"enonce":"On oublie le lavage après l’ajout du conjugué. Que voit-on ?","aide":"À quoi sert un lavage : que retire-t-il ?","type":"choix","options":[{"id":"a","texte":"Seuls les puits contenant l’antigène se colorent, comme si le lavage avait bien été fait"},{"id":"b","texte":"Aucun puits ne se colore, car le conjugué en excès détruit l’antigène qui était fixé au fond"},{"id":"c","texte":"Seul le puits du témoin positif se colore, car les autres puits sont vidés par l’oubli du lavage"},{"id":"d","texte":"Tous les puits se colorent, car le conjugué libre transforme le substrat même sans antigène"}],"multiple":false}]}$ex$::jsonb,
