  ('4c522328-b9f4-5090-93d1-4e4172fdd5d8'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Groupage sanguin sur lame","competence":"lire-tableau","situation":"Quatre patients sont testés avec trois réactifs contenant des anticorps : anti-A, anti-B et anti-D. Une goutte de sang est mélangée à chaque réactif, sur une lame.","documents":[{"id":"groupage","type":"tableau","titre":"Résultats de l’agglutination","colonnes":["Sang de","Anti-A","Anti-B","Anti-D"],"lignes":[["Patient 1","agglutine","non","agglutine"],["Patient 2","non","agglutine","non"],["Patient 3","non","non","non"],["Patient 4","agglutine","agglutine","agglutine"]],"enteteLignes":true,"source":"Résultats imaginés pour l’exercice"}],"questions":[{"enonce":"Relie chaque patient à son groupe sanguin.","aide":"Anti-A et anti-B donnent le groupe, anti-D donne le rhésus : agglutination = antigène présent.","type":"association","gauche":[{"id":"g0","texte":"Patient 1"},{"id":"g1","texte":"Patient 2"},{"id":"g2","texte":"Patient 3"},{"id":"g3","texte":"Patient 4"}],"droite":[{"id":"d0","texte":"B négatif"},{"id":"d1","texte":"O négatif"},{"id":"d2","texte":"AB positif"},{"id":"d3","texte":"A positif"}]},{"enonce":"Pourquoi voit-on des agglutinats à l’œil nu ?","aide":"Les antigènes sont ici portés par des cellules entières.","type":"choix","options":[{"id":"a","texte":"Chaque anticorps est couplé à une enzyme qui transforme un substrat en produit coloré visible"},{"id":"b","texte":"Chaque anticorps a deux bras et relie plusieurs globules rouges, qui forment des amas visibles"},{"id":"c","texte":"Chaque anticorps dissout la membrane des globules rouges, ce qui colore le mélange en rouge foncé"},{"id":"d","texte":"Chaque anticorps diffuse dans le sang et forme avec l’antigène un arc de précipitation en gel"}],"multiple":false},{"enonce":"Combien de ces patients portent l’antigène D (rhésus positif) ?","aide":"Regarde la colonne anti-D.","type":"nombre"}]}$ex$::jsonb,
