   $ex${"titre":"Doser le glucose par la méthode GOD-POD","competence":"observer-schema","situation":"On dose le glucose d’un plasma avec deux enzymes. Réactions : glucose + O₂ → acide gluconique + H₂O₂ (glucose oxydase) ; 2 H₂O₂ + chromogène → chromophore rose + 4 H₂O (peroxydase).","documents":[{"id":"godpod","type":"chaine","disposition":"colonne","titre":"Deux réactions couplées","noeuds":[{"id":"z1","texte":"Glucose"},{"id":"z2","texte":"Peroxyde d’hydrogène (H₂O₂)"},{"id":"z3","texte":"Chromophore rose"}],"liens":[{"de":"z1","a":"z2","texte":"glucose oxydase"},{"de":"z2","a":"z3","texte":"peroxydase + chromogène"}]}],"questions":[{"enonce":"Touche la molécule dont on cherche la concentration.","aide":"On dose le substrat de départ.","type":"zone","document":"godpod","multiple":false},{"enonce":"Touche la molécule dont on mesure l’absorbance.","aide":"Seule une molécule colorée absorbe à la longueur d’onde choisie.","type":"zone","document":"godpod","multiple":false},{"enonce":"Combien de moles de glucose faut-il pour former 1 mole de chromophore ?","aide":"Suis les coefficients : 1 glucose donne combien de H₂O₂, et combien faut-il de H₂O₂ pour un chromophore ?","type":"nombre","unite":"mol"},{"enonce":"Dans ce dosage en point final, quels éléments sont en excès ?","aide":"Le substrat à doser doit être la molécule limitante.","type":"choix","options":[{"id":"a","texte":"Les enzymes et les autres réactifs : seul le glucose limite la réaction"},{"id":"b","texte":"Le chromophore : on le met en excès pour que l’absorbance soit la plus grande possible"},{"id":"c","texte":"Le glucose : on le met en excès pour que les enzymes travaillent à vitesse maximale"},{"id":"d","texte":"Rien n’est en excès : tous les réactifs sont exactement dans les proportions des équations"}],"multiple":false}]}$ex$::jsonb,
