  ('5d52c5a0-de5d-57f3-a573-90603f89a10d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Mesurer une activité enzymatique","competence":"modeliser","situation":"On mesure l’activité d’une phosphatase alcaline dans un sérum : le substrat est en excès, et on suit l’absorbance à 405 nm du produit coloré au cours du temps.","documents":[{"id":"cinetique","type":"graphique","forme":"courbe","titre":"Absorbance à 405 nm en fonction du temps","categories":["0","1","2","3","4","5","6","7","8"],"series":[{"nom":"A405","valeurs":[0,0.037,0.074,0.111,0.148,0.17,0.183,0.19,0.194],"teinte":"turquoise"}],"axeY":{"titre":"Absorbance","min":0,"max":0.2,"pas":0.05},"axeX":{"titre":"Temps (min)"},"valeurs":false,"source":"Mesures idéalisées"},{"id":"params","type":"tableau","titre":"Conditions de la mesure","colonnes":["Paramètre","Valeur"],"lignes":[["Coefficient d’absorption molaire ε","18 500 L·mol⁻¹·cm⁻¹"],["Trajet optique ℓ","1 cm"],["Volume réactionnel dans la cuve","3,0 mL"],["Prise d’essai de sérum","0,15 mL"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le dernier point de la période initiale, où la courbe est encore une droite.","aide":"Cherche où la courbe commence à s’infléchir.","type":"zone","document":"cinetique","multiple":false},{"enonce":"Calcule la pente ΔA / Δt de la période initiale, en min⁻¹.","aide":"Pente = variation d’absorbance ÷ durée, entre 0 et 4 min.","type":"nombre","unite":"min⁻¹"},{"enonce":"Quelle vitesse de formation du produit cela représente-t-il dans la cuve, en µmol·L⁻¹·min⁻¹ ?","aide":"Divise la pente par ε × ℓ : on obtient des mol·L⁻¹·min⁻¹, à convertir en µmol.","type":"nombre","unite":"µmol·L⁻¹·min⁻¹"},{"enonce":"Quelle est la concentration d’activité du sérum, en U·L⁻¹ ?","aide":"Quantité transformée par minute dans 3,0 mL, rapportée à la prise d’essai de 0,15 mL.","type":"nombre","unite":"U·L⁻¹"},{"enonce":"Un élève calcule la pente entre 6 et 8 min. Que trouve-t-il ?","aide":"Regarde la forme de la courbe après 4 minutes.","type":"choix","options":[{"id":"a","texte":"Une pente plus faible : l’activité est sous-estimée, car la vitesse a déjà chuté"},{"id":"b","texte":"La même pente, car la vitesse d’une réaction enzymatique est toujours constante au cours du temps"},{"id":"c","texte":"Une pente nulle, car l’enzyme est détruite dès que l’absorbance dépasse la valeur de 0,15"},{"id":"d","texte":"Une pente plus forte : l’activité est surestimée, car le produit s’accumule et accélère la réaction"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"La courbe est une droite de 0 à **4 min** ; ensuite la vitesse diminue."},{"cle":{"type":"nombre","valeur":0.037,"tolerance":0.001},"affichage":"0,037 min⁻¹","explication":"0,148 ÷ 4 = **0,037 min⁻¹**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0.05},"affichage":"2 µmol·L⁻¹·min⁻¹","explication":"0,037 ÷ 18 500 = 2,0 × 10⁻⁶ mol·L⁻¹·min⁻¹ = **2,0 µmol·L⁻¹·min⁻¹**."},{"cle":{"type":"nombre","valeur":40,"tolerance":0.5},"affichage":"40 U·L⁻¹","explication":"Dans 3,0 mL : 2,0 × 3,0 × 10⁻³ = 6,0 × 10⁻³ µmol·min⁻¹, apportés par 0,15 mL de sérum : 6,0 × 10⁻³ ÷ 0,15 × 10⁻³ = **40 U·L⁻¹**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Après la période initiale, la courbe s’aplatit : la pente est plus faible, donc l’activité est **sous-estimée**. On mesure toujours la vitesse **initiale**."}]$ex$::jsonb),
  ('f53b35e2-4bb8-57f0-a8b9-26eb30832d54'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un cycle de PCR","competence":"observer-schema","situation":"La PCR copie une séquence cible en répétant un cycle de trois étapes. Le schéma montre un cycle.","documents":[{"id":"pcr","type":"chaine","disposition":"cycle","titre":"Un cycle de PCR","noeuds":[{"id":"z1","texte":"Dénaturation, environ 95 °C"},{"id":"z2","texte":"Hybridation des amorces"},{"id":"z3","texte":"Élongation, 72 °C"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z1"}]}],"questions":[{"enonce":"Touche l’étape où agit la Taq polymérase.","aide":"La polymérase fabrique le brin complémentaire.","type":"zone","document":"pcr","multiple":false},{"enonce":"Pourquoi utilise-t-on la Taq polymérase, issue d’une bactérie de sources chaudes ?","aide":"Regarde la température de la première étape.","type":"choix","options":[{"id":"a","texte":"Elle copie l’ARN en ADN, ce qui permet d’amplifier directement le génome des rétrovirus"},{"id":"b","texte":"Elle fonctionne mieux à froid, ce qui permet de se passer de l’étape de dénaturation"},{"id":"c","texte":"Elle ouvre elle-même la double hélice, ce qui rend les amorces inutiles au début du cycle"},{"id":"d","texte":"Elle résiste aux 95 °C de la dénaturation : on n’a pas à en rajouter à chaque cycle"}],"multiple":false},{"enonce":"Combien de copies au maximum obtient-on après 5 cycles à partir d’une seule molécule ?","aide":"Le nombre de copies double à chaque cycle : 2ⁿ.","type":"nombre"},{"enonce":"Dans le tube témoin sans ADN, une bande apparaît après la PCR. Que conclure ?","aide":"Un tube sans ADN ne doit rien amplifier.","type":"choix","options":[{"id":"a","texte":"Les amorces ont fabriqué de l’ADN à partir de rien, ce qui arrive lorsque le cycle est trop long"},{"id":"b","texte":"Il y a eu une contamination par de l’ADN étranger : les résultats sont à refaire"},{"id":"c","texte":"Le témoin est positif : le mélange réactionnel est efficace et on peut valider les autres tubes"},{"id":"d","texte":"La PCR fonctionne bien, car une bande prouve que les amorces se sont fixées sur la cible"}],"multiple":false}]}$ex$::jsonb,
