  ('39d6b899-958c-5a26-9b2a-21517fdf1c6f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Quel acide est le plus fort ?","competence":"lire-graphique","situation":"Au laboratoire, quatre couples acide/base sont rangés sur l’étagère. Inès compare leurs pKa pour choisir l’acide le plus fort et préparer un tampon.","documents":[{"id":"pka","type":"graphique","forme":"barres-h","titre":"pKa à 25 °C","categories":["CH₃COOH / CH₃COO⁻","NH₄⁺ / NH₃","HCOOH / HCOO⁻","C₆H₅COOH / C₆H₅COO⁻"],"series":[{"nom":"pKa","valeurs":[4.8,9.2,3.8,4.2]}],"axeY":{"titre":"pKa","min":0,"max":10,"pas":2},"valeurs":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche le couple dont l’acide est le plus fort.","aide":"Plus le pKa est petit, plus l’acide est fort.","type":"zone","document":"pka","multiple":false},{"enonce":"Une solution d’acide éthanoïque a un pH de 5,8. Que vaut le rapport [CH₃COO⁻] / [CH₃COOH] ?","aide":"pH − pKa = log([A⁻] / [AH]). Ici pH − pKa = 1.","type":"nombre"},{"enonce":"Un tampon contient 0,10 mol/L de CH₃COOH et 0,20 mol/L de CH₃COO⁻. Quel est son pH (arrondi au dixième) ?","aide":"pH = pKa + log(0,20 / 0,10). log 2 ≈ 0,30.","type":"nombre"},{"enonce":"Trie chaque situation selon l’espèce qui prédomine.","aide":"Compare le pH au pKa du couple : pH < pKa, pH = pKa ou pH > pKa.","type":"categories","categories":[{"id":"c0","texte":"Forme acide AH"},{"id":"c1","texte":"Forme basique A⁻"},{"id":"c2","texte":"Égalité [AH] = [A⁻]"}],"items":[{"id":"i0","texte":"C₆H₅COOH / C₆H₅COO⁻ à pH 3,0"},{"id":"i1","texte":"HCOOH / HCOO⁻ à pH 5,0"},{"id":"i2","texte":"CH₃COOH / CH₃COO⁻ à pH 6,0"},{"id":"i3","texte":"NH₄⁺ / NH₃ à pH 7,0"},{"id":"i4","texte":"CH₃COOH / CH₃COO⁻ à pH 4,8"}]}]}$ex$::jsonb,
