  ('f12e38d2-1bbb-58a3-9054-034ff1d1fda1'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le polarimètre et le sucre","competence":"lire-graphique","situation":"Un polarimètre mesure l’angle α dont une solution de saccharose fait tourner la lumière polarisée. Le saccharose a un pouvoir rotatoire spécifique [α] = + 66,5 °·dm⁻¹·g⁻¹·mL. La courbe est tracée avec un tube de longueur ℓ = 2,0 dm.","documents":[{"id":"biot","type":"graphique","forme":"courbe","titre":"Angle mesuré selon la concentration","categories":["0","0,02","0,04","0,06","0,08","0,1"],"series":[{"nom":"α","valeurs":[0,2.66,5.32,7.98,10.64,13.3]}],"axeY":{"titre":"α","unite":"°","min":0,"max":14,"pas":2},"axeX":{"titre":"Concentration c (g/mL)"},"valeurs":false,"source":"Loi de Biot"}],"questions":[{"enonce":"Touche le point de la droite qui correspond à une concentration de 0,08 g/mL.","aide":"Repère l’abscisse 0,08 sur l’axe horizontal.","type":"zone","document":"biot","multiple":false},{"enonce":"Lis l’angle α pour c = 0,06 g/mL.","aide":"Regarde la hauteur du point d’abscisse 0,06.","type":"nombre","unite":"°"},{"enonce":"Que vaut le produit [α] × ℓ, en °·mL·g⁻¹ ? C’est le coefficient directeur de la droite.","aide":"Multiplie 66,5 par 2,0, ou divise α par c pour un point.","type":"nombre","unite":"°·mL·g⁻¹"},{"enonce":"Dans le même tube, une boisson sucrée donne α = + 3,99°. Quelle est sa concentration en saccharose, en g/L ?","aide":"c = α ÷ 133 en g/mL ; multiplie par 1 000 pour obtenir des g/L.","type":"nombre","unite":"g/L"},{"enonce":"On refait la mesure de la même boisson avec un tube de 1,0 dm. Que devient α ?","aide":"Relis la loi : α = [α] × ℓ × c.","type":"choix","options":[{"id":"a","texte":"Il est multiplié par deux, car un tube plus court concentre la solution"},{"id":"b","texte":"Il devient nul, car la lumière traverse trop peu de solution"},{"id":"c","texte":"Il est divisé par deux, car α est proportionnelle à la longueur ℓ"},{"id":"d","texte":"Il reste identique, car α ne dépend que de la concentration"}],"multiple":false}]}$ex$::jsonb,
