  ('1b6b2048-27f4-5cdc-8c4d-f4264c9cb325'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Quelle verrerie choisir ?","competence":"lire-tableau","situation":"Pour préparer une solution, Clara hésite entre plusieurs verreries. Chaque verrerie porte une tolérance ± Δ. Pour une seule mesure, l’incertitude-type de type B vaut u = Δ ÷ √3.","documents":[{"id":"verrerie","type":"tableau","titre":"Tolérances des verreries","colonnes":["Verrerie","Volume","Tolérance ± Δ"],"lignes":[["Pipette jaugée","10,00 mL","0,02 mL"],["Éprouvette graduée","25 mL","0,5 mL"],["Fiole jaugée","100,0 mL","0,08 mL"],["Burette graduée","25,00 mL","0,05 mL"]],"enteteLignes":true,"source":"Valeurs usuelles arrondies"}],"questions":[{"enonce":"Calcule l’incertitude-type u de la pipette jaugée, en mL (arrondie à trois décimales).","aide":"u = 0,02 ÷ √3, avec √3 ≈ 1,73.","type":"nombre","unite":"mL"},{"enonce":"Calcule l’incertitude-type relative de l’éprouvette graduée, en % (arrondie au dixième).","aide":"u = 0,5 ÷ √3, puis divise par 25 et multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Touche la verrerie dont la tolérance relative Δ ÷ volume est la plus petite.","aide":"Calcule Δ ÷ volume pour chaque ligne : 0,2 %, 2 %, ?, 0,2 %.","type":"zone","document":"verrerie","multiple":false},{"enonce":"Pourquoi un prélèvement à l’éprouvette dégrade-t-il le résultat d’un titrage ?","aide":"On additionne les carrés des incertitudes relatives : la plus grande domine.","type":"choix","options":[{"id":"a","texte":"Son incertitude relative est beaucoup plus grande que celle des autres sources, elle domine"},{"id":"b","texte":"Son incertitude relative est nulle, donc les autres sources deviennent dominantes"},{"id":"c","texte":"Elle modifie la concentration du titrant, ce qui décale le volume équivalent"},{"id":"d","texte":"Elle ajoute une erreur aléatoire qui disparaît dès qu’on répète trois fois la mesure"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.012,"tolerance":0.001},"affichage":"0,012 mL","explication":"u = 0,02 ÷ 1,73 ≈ **0,012 mL**."},{"cle":{"type":"nombre","valeur":1.2,"tolerance":0.05},"affichage":"1,2 %","explication":"u ≈ 0,29 mL ; 0,29 ÷ 25 ≈ 0,0116, soit **1,2 %**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Fiole jaugée : 0,08 ÷ 100 = 0,08 %, contre 0,2 %, 2 % et 0,2 % : c’est la plus précise en valeur relative."},{"cle":{"type":"choix","ids":["a"]},"explication":"Avec 1,2 % contre 0,1 % pour les autres sources, l’éprouvette **domine** l’incertitude finale."}]$ex$::jsonb),
  ('1b6b2048-27f4-5cdc-8c4d-f4264c9cb325'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Cinq titrages, une incertitude","competence":"calculer","situation":"Nolan répète cinq fois le même titrage et note le volume équivalent. Il veut exprimer son résultat avec une incertitude de type A : u = s ÷ √n, où s est l’écart-type des mesures.","documents":[{"id":"essais","type":"tableau","titre":"Volumes équivalents mesurés","colonnes":["Essai","1","2","3","4","5"],"lignes":[["V_E (mL)","12,3","12,4","12,5","12,4","12,9"]],"enteteLignes":true,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche la mesure qui s’écarte le plus des autres.","aide":"Compare les cinq valeurs : laquelle est isolée ?","type":"zone","document":"essais","multiple":false},{"enonce":"Calcule la moyenne des cinq volumes, en mL.","aide":"Additionne les cinq valeurs et divise par 5.","type":"nombre","unite":"mL"},{"enonce":"L’écart-type vaut s = √(Σ(xᵢ − x̄)² ÷ 4). Donne s en mL, arrondi au centième.","aide":"Les écarts à la moyenne valent −0,2 ; −0,1 ; 0 ; −0,1 ; +0,4. Élève-les au carré, additionne, divise par 4.","type":"nombre","unite":"mL"},{"enonce":"Calcule l’incertitude-type de type A, u = s ÷ √5, en mL, arrondie au centième.","aide":"Divise 0,2345 par √5, soit environ 2,24.","type":"nombre","unite":"mL"},{"enonce":"La valeur de référence est 12,6 mL. Calcule z = |x − x_réf| ÷ u, arrondi au dixième.","aide":"x = 12,5 mL et u ≈ 0,10 mL.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c5"]},"explication":"Le 5ᵉ essai, **12,9 mL**, s’écarte de 0,4 mL de la moyenne, contre 0,2 mL au plus pour les autres."},{"cle":{"type":"nombre","valeur":12.5,"tolerance":0.01},"affichage":"12,5 mL","explication":"(12,3 + 12,4 + 12,5 + 12,4 + 12,9) ÷ 5 = **12,5 mL**."},{"cle":{"type":"nombre","valeur":0.23,"tolerance":0.005},"affichage":"0,23 mL","explication":"Somme des carrés = 0,22 ; s = √(0,22 ÷ 4) ≈ **0,23 mL**."},{"cle":{"type":"nombre","valeur":0.1,"tolerance":0.005},"affichage":"0,1 mL","explication":"u = 0,2345 ÷ 2,236 ≈ **0,10 mL**."},{"cle":{"type":"nombre","valeur":1,"tolerance":0.1},"affichage":"1","explication":"z = 0,1 ÷ 0,10 ≈ **1,0** : z ≤ 2, le résultat est compatible avec la référence."}]$ex$::jsonb),
  ('1b6b2048-27f4-5cdc-8c4d-f4264c9cb325'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quelle source d’erreur attaquer ?","competence":"modeliser","situation":"Un titrage donne c = c₁ × V_E ÷ V₀. Pour améliorer son protocole, Sacha dresse l’inventaire des incertitudes-types de chaque grandeur, puis les combine avec u(c) ÷ c = √[(u(c₁)÷c₁)² + (u(V_E)÷V_E)² + (u(V₀)÷V₀)²].","documents":[{"id":"sources","type":"tableau","titre":"Les trois sources","colonnes":["Grandeur","Valeur","Incertitude-type"],"lignes":[["c₁ (titrant)","0,200 mol/L","0,001 mol/L"],["V_E (volume équivalent)","15,2 mL","0,10 mL"],["V₀ (prise d’essai)","20,00 mL","0,03 mL"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Calcule la concentration c de la solution titrée, en mol/L.","aide":"c = 0,200 × 15,2 ÷ 20,00.","type":"nombre","unite":"mol/L"},{"enonce":"Calcule l’incertitude relative de V_E, en % (arrondie au centième).","aide":"u(V_E) ÷ V_E = 0,10 ÷ 15,2.","type":"nombre","unite":"%"},{"enonce":"Touche la grandeur dont l’incertitude relative est la plus grande.","aide":"Calcule u ÷ valeur pour chaque ligne : 0,50 % pour c₁ et 0,15 % pour V₀.","type":"zone","document":"sources","multiple":false},{"enonce":"Combine les trois incertitudes relatives 0,50 % ; 0,66 % ; 0,15 % et donne u(c) ÷ c en %, arrondi au centième.","aide":"Additionne les carrés 0,25 ; 0,433 ; 0,0225 puis prends la racine carrée.","type":"nombre","unite":"%"},{"enonce":"Donne l’incertitude-type u(c) en mol/L, arrondie à quatre décimales.","aide":"u(c) = c × 0,0084.","type":"nombre","unite":"mol/L"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.152,"tolerance":0.001},"affichage":"0,152 mol/L","explication":"c = 0,200 × 15,2 ÷ 20,00 = **0,152 mol/L**."},{"cle":{"type":"nombre","valeur":0.66,"tolerance":0.01},"affichage":"0,66 %","explication":"0,10 ÷ 15,2 ≈ 0,0066, soit **0,66 %**. Celle de c₁ vaut 0,50 % et celle de V₀ 0,15 %."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Le volume équivalent, à 0,66 %, domine : c₁ est à 0,50 % et V₀ à 0,15 %."},{"cle":{"type":"nombre","valeur":0.84,"tolerance":0.01},"affichage":"0,84 %","explication":"√(0,25 + 0,433 + 0,0225) ≈ 0,84 : **0,84 %**. On n’additionne jamais directement les incertitudes relatives."},{"cle":{"type":"nombre","valeur":0.0013,"tolerance":0.0001},"affichage":"0,0013 mol/L","explication":"u(c) = 0,152 × 0,0084 ≈ **0,0013 mol/L** : c = 0,1520 ± 0,0013 mol/L."}]$ex$::jsonb),
  ('0b76c6f9-d740-5ff8-9d51-0e08e7206d5d'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le ressort et la bobine","competence":"calculer","situation":"Au laboratoire, on compare deux oscillateurs libres et non amortis : une masse accrochée à un ressort, et un circuit LC. Leurs caractéristiques sont relevées dans le tableau.","documents":[{"id":"oscillateurs","type":"tableau","titre":"Deux oscillateurs","colonnes":["Oscillateur","Caractéristiques"],"enteteLignes":true,"lignes":[["Masse-ressort","m = 0,100 kg ; k = 40,0 N/m"],["Circuit LC","L = 0,100 H ; C = 10,0 µF"]],"source":"Valeurs choisies pour l’exercice"}],"questions":[{"enonce":"Calcule la période propre T₀ de l’oscillateur masse-ressort, en secondes. On donne T₀ = 2π √(m / k).","aide":"Calcule d’abord m / k = 0,100 ÷ 40,0, puis la racine carrée.","type":"nombre","unite":"s"},{"enonce":"Calcule la période propre du circuit LC, en millisecondes. On donne T₀ = 2π √(L × C). Attention : 10,0 µF = 10,0 × 10⁻⁶ F.","aide":"L × C = 0,100 × 10,0 × 10⁻⁶ = 1,00 × 10⁻⁶ s².","type":"nombre","unite":"ms"},{"enonce":"Touche la case de l’oscillateur dont la période propre est la plus courte.","aide":"Compare les deux périodes que tu viens de calculer, après avoir mis la même unité.","type":"zone","document":"oscillateurs","multiple":false},{"enonce":"Relie chaque grandeur du système mécanique à son analogue dans le circuit électrique.","aide":"La masse se comporte comme l’inertie électrique du circuit : celle de la bobine.","type":"association","gauche":[{"id":"g0","texte":"Masse m"},{"id":"g1","texte":"Raideur k"},{"id":"g2","texte":"Énergie cinétique"}],"droite":[{"id":"d0","texte":"Énergie magnétique de la bobine"},{"id":"d1","texte":"Inductance L"},{"id":"d2","texte":"Inverse de la capacité, 1 / C"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.314,"tolerance":0.005},"affichage":"0,314 s","explication":"m / k = 0,0025 s², donc T₀ = 2π × 0,05 ≈ **0,314 s**."},{"cle":{"type":"nombre","valeur":6.28,"tolerance":0.05},"affichage":"6,28 ms","explication":"T₀ = 2π × 1,00 × 10⁻³ ≈ 6,28 × 10⁻³ s, soit **6,28 ms**."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Le circuit LC oscille en 6,28 ms, le masse-ressort en 314 ms : c’est le **circuit LC** qui a la période la plus courte."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Les deux oscillateurs suivent le même modèle : **masse ↔ inductance**, **raideur ↔ 1 / C**, **énergie cinétique ↔ énergie magnétique**."}]$ex$::jsonb),
  ('0b76c6f9-d740-5ff8-9d51-0e08e7206d5d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le vibreur qui fait danser l’oscillateur","competence":"lire-graphique","situation":"Un vibreur impose sa fréquence à deux oscillateurs, A et B, qui ont la même fréquence propre mais des frottements différents. On note l’amplitude de leurs oscillations quand la fréquence du vibreur varie de 7 à 13 Hz.","documents":[{"id":"courbes","type":"graphique","forme":"courbe","titre":"Amplitude en fonction de la fréquence imposée","categories":["7","8","9","10","11","12","13"],"series":[{"nom":"Oscillateur A","valeurs":[1.6,2.4,4.5,10,4.5,2.4,1.6]},{"nom":"Oscillateur B","valeurs":[1.4,1.8,2.2,2.5,2.2,1.8,1.4]}],"axeY":{"titre":"Amplitude","unite":"cm","min":0,"max":12,"pas":2},"axeX":{"titre":"Fréquence imposée (Hz)"},"valeurs":false,"source":"Mesures idéalisées"},{"id":"bande","type":"tableau","titre":"Largeur de la bande passante","colonnes":["Oscillateur","Largeur Δf (Hz)"],"enteteLignes":true,"lignes":[["Oscillateur A","1,0"],["Oscillateur B","4,0"]]}],"questions":[{"enonce":"Touche la fréquence de résonance des deux oscillateurs.","aide":"Cherche la fréquence où les deux amplitudes sont maximales.","type":"zone","document":"courbes","multiple":false},{"enonce":"Calcule le facteur de qualité de l’oscillateur A. On donne Q = f₀ / Δf.","aide":"Prends f₀ sur le graphique et Δf dans le tableau.","type":"nombre"},{"enonce":"Calcule le facteur de qualité de l’oscillateur B.","aide":"Même calcul, avec la largeur de bande passante de B.","type":"nombre"},{"enonce":"Quel oscillateur est le plus amorti, et comment le voit-on ?","aide":"Un oscillateur très amorti a une résonance peu marquée.","type":"choix","options":[{"id":"a","texte":"L’oscillateur A : son amplitude à la résonance est la plus grande, donc il dissipe le plus d’énergie"},{"id":"b","texte":"L’oscillateur A : sa bande passante est la plus étroite, donc ses frottements sont les plus forts"},{"id":"c","texte":"L’oscillateur B : son facteur de qualité est le plus faible et sa résonance la plus large"},{"id":"d","texte":"Aucun des deux n’est plus amorti, car ils ont la même fréquence propre de 10 Hz"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Les deux courbes culminent à **10 Hz** : c’est la fréquence propre f₀, donc celle de la résonance."},{"cle":{"type":"nombre","valeur":10,"tolerance":0.1},"affichage":"10","explication":"Q = 10 ÷ 1,0 = **10**."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0.05},"affichage":"2,5","explication":"Q = 10 ÷ 4,0 = **2,5**."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’oscillateur **B** a Q = 2,5 et une courbe aplatie : ses frottements sont plus forts. A, très peu amorti, a une résonance aiguë."}]$ex$::jsonb),
  ('0b76c6f9-d740-5ff8-9d51-0e08e7206d5d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le haut-parleur, la porte et le spectre","competence":"analyser-document","situation":"Un haut-parleur émet un son périodique de fréquence 2,0 kHz. Deux microphones alignés avec lui enregistrent le signal avec un retard (premier document), et on relève son spectre. L’onde traverse ensuite une porte ouverte de largeur a = 34 cm. Célérité attendue dans l’air : 340 m/s.","documents":[{"id":"retards","type":"tableau","titre":"Retard du signal selon la distance","colonnes":["Distance à la source (cm)","20","40","60"],"enteteLignes":true,"lignes":[["Retard (ms)","0,59","1,18","1,76"]],"source":"Mesures idéalisées"},{"id":"spectre","type":"graphique","forme":"barres","titre":"Spectre du signal","categories":["0","2","4","6","8"],"series":[{"nom":"Amplitude","valeurs":[0.4,1,0.6,0.3,0.1]}],"axeY":{"titre":"Amplitude","unite":"unité arbitraire","min":0,"max":1.2,"pas":0.2},"axeX":{"titre":"Fréquence (kHz)"},"valeurs":false}],"questions":[{"enonce":"Calcule la célérité mesurée avec le microphone le plus éloigné (60 cm, retard 1,76 ms). On donne τ = d / v.","aide":"Convertis 60 cm en mètres et 1,76 ms en secondes avant de diviser.","type":"nombre","unite":"m/s"},{"enonce":"Quelle est la longueur d’onde du son de 2,0 kHz, en centimètres ? On donne λ = v / f.","aide":"λ = 340 ÷ 2 000 donne des mètres.","type":"nombre","unite":"cm"},{"enonce":"Touche la raie du fondamental de ce signal.","aide":"Le fondamental a la fréquence du signal, 2,0 kHz.","type":"zone","document":"spectre","multiple":false},{"enonce":"Que traduit la raie située à 0 kHz ?","aide":"Une composante de fréquence nulle ne varie pas dans le temps.","type":"choix","options":[{"id":"a","texte":"Le signal ne transporte aucune énergie, car sa fréquence est nulle"},{"id":"b","texte":"Le signal contient un son très grave, audible mais inférieur à 20 Hz"},{"id":"c","texte":"Le signal a une valeur moyenne non nulle, autour de laquelle il oscille"},{"id":"d","texte":"Le microphone capte aussi le bruit du réseau électrique à 50 Hz"}],"multiple":false},{"enonce":"Le demi-angle de la tache centrale de diffraction par la porte vaut θ ≈ λ / a. Calcule θ, en radians.","aide":"Utilise λ = 0,17 m et a = 0,34 m, dans la même unité.","type":"nombre","unite":"rad"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":340,"tolerance":5},"affichage":"340 m/s","explication":"v = d / τ = 0,60 ÷ 1,76 × 10⁻³ ≈ **340 m/s**."},{"cle":{"type":"nombre","valeur":17,"tolerance":0.5},"affichage":"17 cm","explication":"λ = 340 ÷ 2 000 = 0,17 m = **17 cm**."},{"cle":{"type":"zone","ids":["k1"]},"explication":"Le fondamental est la raie à **2 kHz** ; les raies de 4, 6 et 8 kHz sont ses harmoniques (2f, 3f, 4f)."},{"cle":{"type":"choix","ids":["c"]},"explication":"La composante de fréquence nulle est la **valeur moyenne** du signal, ici non nulle."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0.02},"affichage":"0,5 rad","explication":"θ ≈ 0,17 ÷ 0,34 = **0,50 rad** : le son s’étale largement derrière la porte, car λ est comparable à a."}]$ex$::jsonb),
  ('2a4b0a15-a0ef-5340-bf76-4fd766fa655e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La corde de guitare en deux fuseaux","competence":"observer-schema","situation":"Une corde de guitare de longueur L = 60 cm, fixée à ses deux extrémités, vibre sur son deuxième mode propre. Le schéma la montre figée à un instant. La célérité des ondes sur la corde est v = 240 m/s.","documents":[{"id":"corde","type":"schema","titre":"Corde en vibration","largeur":320,"hauteur":230,"elements":[{"forme":"ligne","de":[30,110],"a":[290,110],"style":"pointilles"},{"forme":"chemin","d":"M30 110 Q95 50 160 110 Q225 170 290 110"},{"forme":"rect","x":20,"y":96,"l":8,"h":28},{"forme":"rect","x":292,"y":96,"l":8,"h":28},{"forme":"cercle","cx":30,"cy":110,"r":7,"id":"z1","zone":true},{"forme":"cercle","cx":160,"cy":110,"r":7,"id":"z2","zone":true},{"forme":"cercle","cx":290,"cy":110,"r":7,"id":"z3","zone":true},{"forme":"cercle","cx":95,"cy":80,"r":7,"id":"z4","zone":true},{"forme":"cercle","cx":225,"cy":140,"r":7,"id":"z5","zone":true},{"forme":"ligne","de":[30,185],"a":[290,185],"fleche":"deux"},{"forme":"texte","x":160,"y":208,"texte":"L = 60 cm","ancre":"milieu"}]}],"questions":[{"enonce":"Touche les trois nœuds de vibration de la corde, c’est-à-dire les points qui ne bougent jamais.","aide":"Un nœud est sur la position de repos de la corde, en pointillés.","type":"zone","document":"corde","multiple":true},{"enonce":"Combien mesure la longueur d’onde λ, en mètres ? Pour n fuseaux, L = n × λ / 2.","aide":"Ici n = 2 : λ = 2L ÷ 2.","type":"nombre","unite":"m"},{"enonce":"Quelle est la fréquence de cette vibration, en hertz ? On donne f = v / λ.","aide":"Divise la célérité par la longueur d’onde que tu viens de trouver.","type":"nombre","unite":"Hz"},{"enonce":"Quelle serait la fréquence du fondamental de cette corde, en hertz ? On donne fₙ = n × v / (2L).","aide":"Le fondamental correspond à n = 1.","type":"nombre","unite":"Hz"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2","z3"]},"explication":"Les **trois nœuds** sont aux deux extrémités fixes et au milieu de la corde. Les deux ventres sont les sommets des fuseaux."},{"cle":{"type":"nombre","valeur":0.6,"tolerance":0.01},"affichage":"0,6 m","explication":"λ = 2L / n = 2 × 0,60 ÷ 2 = **0,60 m**."},{"cle":{"type":"nombre","valeur":400,"tolerance":5},"affichage":"400 Hz","explication":"f₂ = 240 ÷ 0,60 = **400 Hz**."},{"cle":{"type":"nombre","valeur":200,"tolerance":3},"affichage":"200 Hz","explication":"f₁ = 240 ÷ (2 × 0,60) = **200 Hz**, moitié de f₂."}]$ex$::jsonb),
  ('2a4b0a15-a0ef-5340-bf76-4fd766fa655e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’atelier de menuiserie","competence":"lire-tableau","situation":"Un élève mesure l’intensité sonore de trois sources de son lycée. Le niveau d’intensité sonore se calcule par L = 10 × log (I / I₀) avec I₀ = 1,0 × 10⁻¹² W/m². Au-delà de 85 dB, une exposition prolongée abîme l’oreille.","documents":[{"id":"sources","type":"tableau","titre":"Intensités sonores relevées","colonnes":["Source","Intensité I (W/m²)"],"enteteLignes":true,"lignes":[["Conversation","1,0 × 10⁻⁶"],["Aspirateur","1,0 × 10⁻⁵"],["Atelier de menuiserie","1,0 × 10⁻³"]],"source":"Mesures idéalisées"}],"questions":[{"enonce":"Calcule le niveau d’intensité sonore de l’atelier de menuiserie, en décibels.","aide":"I / I₀ = 1,0 × 10⁻³ ÷ 1,0 × 10⁻¹² = 10⁹ : cherche log (10⁹).","type":"nombre","unite":"dB"},{"enonce":"Touche la source dont le niveau dépasse 85 dB.","aide":"Calcule le niveau de chaque source : il grimpe de 10 dB chaque fois que I est multipliée par 10.","type":"zone","document":"sources","multiple":false},{"enonce":"On allume deux aspirateurs identiques. Quel niveau sonore atteint-on, en décibels ? (Le niveau d’un seul est 70 dB.)","aide":"Deux sources identiques doublent l’intensité, pas le niveau.","type":"nombre","unite":"dB"},{"enonce":"Un élève affirme : « Deux aspirateurs de 70 dB font 140 dB. » Pourquoi est-ce faux ?","aide":"Le niveau utilise un logarithme : les décibels ne s’additionnent pas.","type":"choix","options":[{"id":"a","texte":"Ce sont les intensités qui s’ajoutent, pas les décibels : doubler l’intensité ajoute seulement 3 dB"},{"id":"b","texte":"Le niveau en décibels s’additionne seulement quand les deux sources sont très éloignées l’une de l’autre"},{"id":"c","texte":"Le décibel est une unité linéaire mais l’oreille ne perçoit plus rien au-delà de 120 dB"},{"id":"d","texte":"Deux sources identiques s’annulent en partie, donc le niveau reste le même que pour une seule source"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":90,"tolerance":0.5},"affichage":"90 dB","explication":"L = 10 × log (10⁹) = **90 dB**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"La conversation fait 60 dB, l’aspirateur 70 dB, l’**atelier** 90 dB : lui seul dépasse 85 dB."},{"cle":{"type":"nombre","valeur":73,"tolerance":0.5},"affichage":"73 dB","explication":"I = 2 × 1,0 × 10⁻⁵ W/m², donc L = 10 × log (2 × 10⁷) ≈ **73 dB**. Doubler l’intensité ajoute 3 dB."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le logarithme transforme un **doublement d’intensité en +3 dB** : 70 dB + 70 dB donnent environ 73 dB."}]$ex$::jsonb),
  ('2a4b0a15-a0ef-5340-bf76-4fd766fa655e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Flûte ouverte ou bourdon fermé ?","competence":"experimenter","situation":"Deux tuyaux d’orgue de même longueur, L = 0,85 m, sont enregistrés un par un : l’un est ouvert aux deux bouts, l’autre est fermé à une extrémité. Un micro relève les fréquences des trois premiers pics de chaque enregistrement. Célérité du son : v = 340 m/s.","documents":[{"id":"tuyaux","type":"schema","titre":"Les deux tuyaux","largeur":320,"hauteur":240,"elements":[{"forme":"ligne","de":[40,40],"a":[40,190]},{"forme":"ligne","de":[80,40],"a":[80,190]},{"forme":"ligne","de":[40,40],"a":[80,40],"style":"pointilles","id":"z1","zone":true},{"forme":"ligne","de":[40,190],"a":[80,190],"style":"pointilles","id":"z2","zone":true},{"forme":"ligne","de":[140,40],"a":[140,190]},{"forme":"ligne","de":[180,40],"a":[180,190]},{"forme":"ligne","de":[140,40],"a":[180,40],"style":"pointilles","id":"z3","zone":true},{"forme":"rect","x":138,"y":188,"l":44,"h":8,"id":"z4","zone":true},{"forme":"texte","x":60,"y":218,"texte":"Tuyau 1","ancre":"milieu"},{"forme":"texte","x":160,"y":218,"texte":"Tuyau 2","ancre":"milieu"},{"forme":"ligne","de":[225,40],"a":[225,190],"fleche":"deux"},{"forme":"texte","x":238,"y":120,"texte":"L = 0,85 m","ancre":"debut"}]},{"id":"enregistrements","type":"tableau","titre":"Fréquences des trois premiers pics","colonnes":["Enregistrement","Fréquences (Hz)"],"enteteLignes":true,"lignes":[["Enregistrement 1","200 ; 400 ; 600"],["Enregistrement 2","100 ; 300 ; 500"]],"source":"Mesures idéalisées"}],"questions":[{"enonce":"Touche l’extrémité fermée du tuyau 2.","aide":"Cherche la paroi pleine qui bouche le bas du tuyau.","type":"zone","document":"tuyaux","multiple":false},{"enonce":"Touche l’enregistrement qui correspond au tuyau fermé.","aide":"Un tuyau fermé à un bout ne produit que les harmoniques impairs.","type":"zone","document":"enregistrements","multiple":false},{"enonce":"Calcule le fondamental attendu du tuyau fermé, en hertz. On donne fₙ = (2n − 1) × v / (4L), avec n = 1.","aide":"Pour n = 1, le facteur (2n − 1) vaut 1.","type":"nombre","unite":"Hz"},{"enonce":"Un autre tuyau fermé doit avoir un fondamental de 170 Hz. Quelle longueur, en mètres, lui donner ?","aide":"Isole L dans f₁ = v / (4L).","type":"nombre","unite":"m"},{"enonce":"Le fondamental du tuyau fermé est plus grave que celui du tuyau ouvert de même longueur. De combien ?","aide":"Compare 100 Hz et 200 Hz.","type":"choix","options":[{"id":"a","texte":"Un tiers de plus : sa fréquence est divisée par un facteur 1,5"},{"id":"b","texte":"Une octave : sa fréquence est deux fois plus petite"},{"id":"c","texte":"Il n’y a aucune différence, car seule la longueur du tuyau compte"},{"id":"d","texte":"Deux octaves : sa fréquence est quatre fois plus petite"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"L’extrémité fermée est le **fond plein** du tuyau 2 : c’est là que se trouve un nœud de vibration."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Les pics **100 ; 300 ; 500 Hz** sont les multiples impairs du fondamental : c’est le tuyau fermé (enregistrement 2)."},{"cle":{"type":"nombre","valeur":100,"tolerance":2},"affichage":"100 Hz","explication":"f₁ = 340 ÷ (4 × 0,85) = **100 Hz**, ce qu’on lit sur l’enregistrement 2."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0.01},"affichage":"0,5 m","explication":"L = v / (4 f₁) = 340 ÷ (4 × 170) = **0,50 m**."},{"cle":{"type":"choix","ids":["b"]},"explication":"100 Hz est la moitié de 200 Hz : le tuyau fermé sonne **une octave plus grave**."}]$ex$::jsonb),
  ('55da8528-30d5-546e-b1f8-73f54d09aced'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"L’échelle des ondes électromagnétiques","competence":"observer-schema","situation":"On range les ondes électromagnétiques par longueur d’onde, des plus longues aux plus courtes. Célérité de la lumière dans le vide : c = 3,00 × 10⁸ m/s ; constante de Planck : h = 6,63 × 10⁻³⁴ J·s.","documents":[{"id":"spectre","type":"schema","titre":"Les domaines du spectre","largeur":320,"hauteur":232,"elements":[{"forme":"rect","x":10,"y":10,"l":300,"h":36,"arrondi":6,"texte":"Ondes radio · plus de 1 mm","id":"z1","zone":true},{"forme":"rect","x":10,"y":54,"l":300,"h":36,"arrondi":6,"texte":"Infrarouge · 800 nm à 1 mm","id":"z2","zone":true},{"forme":"rect","x":10,"y":98,"l":300,"h":36,"arrondi":6,"texte":"Visible · 400 nm à 800 nm","id":"z3","zone":true},{"forme":"rect","x":10,"y":142,"l":300,"h":36,"arrondi":6,"texte":"Ultraviolet · 10 nm à 400 nm","id":"z4","zone":true},{"forme":"rect","x":10,"y":186,"l":300,"h":36,"arrondi":6,"texte":"Rayons X et gamma · moins de 10 nm","id":"z5","zone":true}]}],"questions":[{"enonce":"Touche le domaine qui contient une radiation de longueur d’onde 550 nm.","aide":"Compare 550 nm aux bornes de chaque domaine.","type":"zone","document":"spectre","multiple":false},{"enonce":"Quelle est la fréquence d’une radiation de longueur d’onde 600 nm, en unités de 10¹⁴ Hz ? On donne f = c / λ.","aide":"Convertis 600 nm en mètres : 600 × 10⁻⁹ m.","type":"nombre","unite":"× 10¹⁴ Hz"},{"enonce":"Quelle est l’énergie d’un photon de cette radiation, en unités de 10⁻¹⁹ J ? On donne E = h × f.","aide":"Utilise f = 5,0 × 10¹⁴ Hz.","type":"nombre","unite":"× 10⁻¹⁹ J"},{"enonce":"Touche le domaine dont les photons sont les plus énergétiques.","aide":"E = h × c / λ : l’énergie grandit quand λ diminue.","type":"zone","document":"spectre","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"550 nm est entre 400 nm et 800 nm : c’est de la **lumière visible**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0.05},"affichage":"5 × 10¹⁴ Hz","explication":"f = 3,00 × 10⁸ ÷ 600 × 10⁻⁹ = 5,0 × 10¹⁴ Hz, soit **5,0** dans l’unité demandée."},{"cle":{"type":"nombre","valeur":3.3,"tolerance":0.05},"affichage":"3,3 × 10⁻¹⁹ J","explication":"E = 6,63 × 10⁻³⁴ × 5,0 × 10¹⁴ ≈ 3,3 × 10⁻¹⁹ J, soit **3,3** dans l’unité demandée."},{"cle":{"type":"zone","ids":["z5"]},"explication":"Les **rayons X et gamma** ont les plus courtes longueurs d’onde, donc les photons les plus énergétiques."}]$ex$::jsonb),
