  ('fe5e37bf-f00c-5b08-9992-580fb53763e9'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un rayon qui entre dans le verre","competence":"observer-schema","situation":"Un rayon de lumière arrive sur la face plane d’un bloc de verre d’indice n = 1,50, avec un angle d’incidence i₁ = 45° mesuré depuis la normale. Plus loin, la lumière naturelle traverse le montage du second document.","documents":[{"id":"refraction","type":"schema","titre":"Passage de l’air au verre","largeur":320,"hauteur":240,"elements":[{"forme":"rect","x":20,"y":120,"l":280,"h":100,"teinte":"ciel","motif":"clair"},{"forme":"ligne","de":[20,120],"a":[300,120],"id":"z1","zone":true},{"forme":"ligne","de":[160,20],"a":[160,220],"style":"pointilles","id":"z2","zone":true},{"forme":"ligne","de":[89,49],"a":[160,120],"fleche":"fin","id":"z3","zone":true},{"forme":"ligne","de":[160,120],"a":[207,208],"fleche":"fin","id":"z4","zone":true},{"forme":"texte","x":200,"y":40,"texte":"Air (n = 1,00)","ancre":"debut"},{"forme":"texte","x":30,"y":212,"texte":"Verre (n = 1,50)","ancre":"debut"},{"forme":"texte","x":122,"y":98,"texte":"i₁"},{"forme":"texte","x":195,"y":160,"texte":"i₂","ancre":"debut"}]},{"id":"polarisation","type":"chaine","titre":"Montage de polarisation","disposition":"ligne","noeuds":[{"id":"z5","texte":"Lumière naturelle"},{"id":"z6","texte":"Polariseur"},{"id":"z7","texte":"Solution de saccharose"},{"id":"z8","texte":"Analyseur"},{"id":"z9","texte":"Détecteur"}],"liens":[{"de":"z5","a":"z6"},{"de":"z6","a":"z7"},{"de":"z7","a":"z8"},{"de":"z8","a":"z9"}]}],"questions":[{"enonce":"Touche la normale à la surface du verre.","aide":"La normale est perpendiculaire à la surface, tracée en pointillés.","type":"zone","document":"refraction","multiple":false},{"enonce":"Calcule l’angle de réfraction i₂, en degrés. Utilise n₁ × sin i₁ = n₂ × sin i₂ avec n₁ = 1,00.","aide":"sin i₂ = sin 45° ÷ 1,50 ≈ 0,471 ; utilise ensuite la touche sin⁻¹ de la calculatrice en degrés.","type":"nombre","unite":"°"},{"enonce":"Dans l’autre sens, du verre vers l’air, il n’y a plus de rayon réfracté au-delà d’un angle limite. Calcule-le, en degrés. On donne sin i_lim = n₂ / n₁.","aide":"Ici n₁ = 1,50 (verre) et n₂ = 1,00 (air) : sin i_lim = 1,00 ÷ 1,50.","type":"nombre","unite":"°"},{"enonce":"Touche l’élément du montage qui ne laisse passer qu’une seule direction de vibration de la lumière.","aide":"La lumière naturelle vibre dans toutes les directions avant de le traverser.","type":"zone","document":"polarisation","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **normale** est la droite en pointillés, perpendiculaire à la surface : les angles se mesurent à partir d’elle, pas à partir de la surface."},{"cle":{"type":"nombre","valeur":28,"tolerance":0.5},"affichage":"28 °","explication":"sin i₂ = 0,707 ÷ 1,50 = 0,471, donc i₂ ≈ **28°** : le rayon se rapproche de la normale dans le milieu plus réfringent."},{"cle":{"type":"nombre","valeur":41.8,"tolerance":0.5},"affichage":"41,8 °","explication":"sin i_lim = 1,00 ÷ 1,50 = 0,667, donc i_lim ≈ **41,8°**. Au-delà, la réflexion est totale."},{"cle":{"type":"zone","ids":["z6"]},"explication":"Le **polariseur** ne laisse passer qu’une direction ; l’analyseur, placé après, sert à repérer la rotation de cette direction."}]$ex$::jsonb),
  ('fe5e37bf-f00c-5b08-9992-580fb53763e9'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"L’épaisseur d’un fil au laser","competence":"experimenter","situation":"Un laser de longueur d’onde 532 nm éclaire successivement deux fils fins ; l’écran est à D = 2,00 m. On mesure la largeur ℓ de la tache centrale de diffraction (tableau). On remplace ensuite le fil par un réseau de pas a = 2,0 µm.","documents":[{"id":"montage","type":"schema","titre":"Montage vu de dessus","largeur":320,"hauteur":190,"elements":[{"forme":"rect","x":10,"y":70,"l":50,"h":30,"arrondi":4,"id":"z1","zone":true},{"forme":"texte","x":35,"y":125,"texte":"Laser","ancre":"milieu"},{"forme":"ligne","de":[60,85],"a":[160,85],"fleche":"fin"},{"forme":"ligne","de":[170,50],"a":[170,120],"id":"z2","zone":true},{"forme":"texte","x":170,"y":140,"texte":"Fil","ancre":"milieu"},{"forme":"ligne","de":[180,85],"a":[290,85],"fleche":"fin"},{"forme":"ligne","de":[295,20],"a":[295,170],"id":"z3","zone":true},{"forme":"rect","x":291,"y":65,"l":8,"h":40,"arrondi":3,"id":"z4","zone":true},{"forme":"texte","x":295,"y":185,"texte":"Écran","ancre":"milieu"},{"forme":"ligne","de":[170,160],"a":[295,160],"fleche":"deux"},{"forme":"texte","x":232,"y":152,"texte":"D = 2,00 m","ancre":"milieu"}]},{"id":"mesures","type":"tableau","titre":"Largeur de la tache centrale","colonnes":["Fil","ℓ (cm)"],"enteteLignes":true,"lignes":[["Fil A","1,6"],["Fil B","3,2"]]}],"questions":[{"enonce":"Touche la tache centrale de diffraction.","aide":"C’est la zone lumineuse et étalée sur l’écran.","type":"zone","document":"montage","multiple":false},{"enonce":"Calcule la largeur a du fil A, en micromètres. Le demi-angle vaut θ = (ℓ / 2) ÷ D, puis a = λ ÷ θ.","aide":"θ = 0,008 ÷ 2,00 = 4,0 × 10⁻³ rad ; a = 532 × 10⁻⁹ ÷ θ.","type":"nombre","unite":"µm"},{"enonce":"Quel fil est le plus fin, et pourquoi ?","aide":"Plus l’obstacle est petit, plus la diffraction est marquée.","type":"choix","options":[{"id":"a","texte":"Les deux fils ont la même largeur, car la longueur d’onde est la même"},{"id":"b","texte":"Le fil B : sa tache est plus large, donc il arrête plus de lumière"},{"id":"c","texte":"Le fil B : sa tache est plus large, donc a = λ ÷ θ est plus petit"},{"id":"d","texte":"Le fil A : sa tache est plus étroite, donc a = λ ÷ θ est plus petit"}],"multiple":false},{"enonce":"Le réseau de pas a = 2,0 µm donne des maxima tels que sin θ = k × λ ÷ a. Calcule sin θ pour k = 1.","aide":"Convertis 2,0 µm en mètres : 2,0 × 10⁻⁶ m.","type":"nombre"},{"enonce":"Déduis-en l’angle θ₁ du premier maximum, en degrés.","aide":"Utilise sin⁻¹ (0,266) sur la calculatrice en degrés.","type":"nombre","unite":"°"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"La **tache centrale** est la zone lumineuse étalée sur l’écran, de largeur ℓ."},{"cle":{"type":"nombre","valeur":133,"tolerance":2},"affichage":"133 µm","explication":"θ = 4,0 × 10⁻³ rad, donc a = 532 × 10⁻⁹ ÷ 4,0 × 10⁻³ ≈ 1,33 × 10⁻⁴ m = **133 µm**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Plus un fil est fin, plus la tache s’élargit. B a une tache deux fois plus large : il est **deux fois plus fin** (66,5 µm)."},{"cle":{"type":"nombre","valeur":0.266,"tolerance":0.003},"affichage":"0,266","explication":"sin θ₁ = 532 × 10⁻⁹ ÷ 2,0 × 10⁻⁶ = **0,266**."},{"cle":{"type":"nombre","valeur":15.4,"tolerance":0.3},"affichage":"15,4 °","explication":"θ₁ = sin⁻¹ (0,266) ≈ **15,4°**."}]$ex$::jsonb),
  ('fe5e37bf-f00c-5b08-9992-580fb53763e9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Haut-parleurs synchrones et sonde Doppler","competence":"analyser-document","situation":"Deux haut-parleurs synchrones émettent un son pur de 500 Hz (célérité 340 m/s). On relève les distances de quatre points M à chaque haut-parleur. Dans un second temps, une sonde Doppler de fréquence 5,0 MHz explore deux vaisseaux sanguins (célérité des ultrasons : 1 540 m/s).","documents":[{"id":"points","type":"tableau","titre":"Distances aux deux haut-parleurs","colonnes":["Point","d₁ (m)","d₂ (m)"],"enteteLignes":true,"lignes":[["M1","3,00","3,68"],["M2","3,00","3,34"],["M3","3,00","4,02"],["M4","3,00","4,36"]],"source":"Mesures idéalisées"},{"id":"doppler","type":"tableau","titre":"Décalage Doppler mesuré","colonnes":["Vaisseau","f reçue − f émise (Hz)"],"enteteLignes":true,"lignes":[["Vaisseau 1","+ 1 300"],["Vaisseau 2","− 3 250"]],"source":"Mesures idéalisées"}],"questions":[{"enonce":"Calcule la longueur d’onde du son, en mètres. On donne λ = v / f.","aide":"λ = 340 ÷ 500.","type":"nombre","unite":"m"},{"enonce":"Touche les deux points où le son est minimal (interférences destructives).","aide":"Calcule δ = d₂ − d₁ puis compare-le à k × λ et à (k + ½) × λ.","type":"zone","document":"points","multiple":true},{"enonce":"Calcule la vitesse du sang dans le vaisseau 1, en m/s. Pour une sonde, Δf ≈ 2 × f × v ÷ c : le décalage est doublé.","aide":"v = Δf × c ÷ (2 × f), avec f = 5,0 × 10⁶ Hz.","type":"nombre","unite":"m/s"},{"enonce":"Calcule la vitesse du sang dans le vaisseau 2, en m/s (valeur positive).","aide":"Même formule, avec la valeur absolue du décalage.","type":"nombre","unite":"m/s"},{"enonce":"Dans le vaisseau 2, la fréquence reçue est plus petite que la fréquence émise. Que fait le sang ?","aide":"Pense à la sirène d’une ambulance qui s’éloigne.","type":"choix","options":[{"id":"a","texte":"Il s’éloigne de la sonde : quand la source et le récepteur s’éloignent, la fréquence monte"},{"id":"b","texte":"Il se rapproche de la sonde : quand la source et le récepteur se rapprochent, la fréquence baisse"},{"id":"c","texte":"Il s’éloigne de la sonde : quand la source et le récepteur s’éloignent, la fréquence baisse"},{"id":"d","texte":"Il est immobile : le décalage vient alors seulement du réglage de la sonde Doppler"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.68,"tolerance":0.01},"affichage":"0,68 m","explication":"λ = 340 ÷ 500 = **0,68 m**."},{"cle":{"type":"zone","ids":["r1c0","r2c0"]},"explication":"δ vaut 0,68 m en M1 (1 λ), 0,34 m en M2 (½ λ), 1,02 m en M3 (1,5 λ), 1,36 m en M4 (2 λ). Les minima sont en **M2 et M3**, où δ = (k + ½) × λ."},{"cle":{"type":"nombre","valeur":0.2,"tolerance":0.01},"affichage":"0,2 m/s","explication":"v = 1 300 × 1 540 ÷ (2 × 5,0 × 10⁶) ≈ **0,20 m/s**."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0.01},"affichage":"0,5 m/s","explication":"v = 3 250 × 1 540 ÷ (2 × 5,0 × 10⁶) ≈ **0,50 m/s**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une fréquence plus petite signifie un **éloignement** : le sang du vaisseau 2 s’éloigne de la sonde."}]$ex$::jsonb),
  ('82b4de1b-b61d-5add-8100-816c07b8661f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les échos de la sonde","competence":"lire-tableau","situation":"Une sonde d’échographie envoie une brève salve d’ultrasons dans les tissus mous (célérité v = 1 540 m/s) et mesure la durée Δt de l’aller-retour de chaque écho. Le tableau donne trois interfaces rencontrées.","documents":[{"id":"echos","type":"tableau","titre":"Échos reçus","colonnes":["Interface","Durée de l’aller-retour Δt (µs)"],"enteteLignes":true,"lignes":[["Peau – graisse","26"],["Graisse – muscle","65"],["Muscle – os","130"]],"source":"Valeurs idéalisées"}],"questions":[{"enonce":"Touche l’interface la plus profonde.","aide":"Plus l’écho revient tard, plus l’interface est loin de la sonde.","type":"zone","document":"echos","multiple":false},{"enonce":"À quelle profondeur se trouve l’interface peau – graisse, en centimètres ? On donne d = v × Δt / 2.","aide":"Convertis 26 µs en secondes : 26 × 10⁻⁶ s. N’oublie pas le « / 2 ».","type":"nombre","unite":"cm"},{"enonce":"Quelle est l’épaisseur de la couche située entre l’interface peau – graisse et l’interface muscle – os, en centimètres ?","aide":"Calcule la profondeur de l’interface muscle – os, puis soustrais 2,0 cm.","type":"nombre","unite":"cm"},{"enonce":"Un quatrième écho revient au bout de 39 µs. À quelle profondeur est l’interface, en centimètres ?","aide":"Même calcul : v × Δt ÷ 2.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
