  ('82b4de1b-b61d-5add-8100-816c07b8661f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Sous le microscope","competence":"observer-schema","situation":"Un élève observe des cellules avec un microscope. Le tube contient deux lentilles convergentes : une près de l’échantillon, l’autre près de l’œil. L’oculaire a une distance focale f’ = 2,0 cm. Le tableau donne les objectifs disponibles.","documents":[{"id":"microscope","type":"schema","titre":"Le microscope","largeur":320,"hauteur":260,"elements":[{"forme":"emoji","x":160,"y":22,"emoji":"👁","taille":26},{"forme":"ligne","de":[130,45],"a":[130,195]},{"forme":"ligne","de":[190,45],"a":[190,195]},{"forme":"ellipse","cx":160,"cy":62,"rx":30,"ry":7,"id":"z1","zone":true},{"forme":"ellipse","cx":160,"cy":180,"rx":22,"ry":6,"id":"z2","zone":true},{"forme":"rect","x":110,"y":222,"l":100,"h":6,"id":"z3","zone":true},{"forme":"texte","x":160,"y":248,"texte":"Échantillon","ancre":"milieu"}]},{"id":"objectifs","type":"tableau","titre":"Objectifs disponibles","colonnes":["Objectif","Grandissement |γ|"],"enteteLignes":true,"lignes":[["Objectif A","× 10"],["Objectif B","× 20"],["Objectif C","× 40"]]}],"questions":[{"enonce":"Touche l’objectif, la lentille qui donne une image réelle agrandie de l’échantillon.","aide":"L’objectif est la lentille la plus proche de l’échantillon.","type":"zone","document":"microscope","multiple":false},{"enonce":"Calcule le grossissement commercial de l’oculaire. On donne G_c = 0,25 ÷ f’ (f’ en mètres).","aide":"Convertis 2,0 cm en mètres : 0,020 m.","type":"nombre"},{"enonce":"Touche l’objectif qui donne un grossissement total de 250 avec cet oculaire. On donne G = |γ| × G_c(oculaire).","aide":"Divise 250 par le grossissement de l’oculaire.","type":"zone","document":"objectifs","multiple":false},{"enonce":"Pour séparer deux détails très proches, limités par la diffraction, que faut-il faire ?","aide":"La résolution s’améliore quand λ diminue et quand l’ouverture numérique augmente.","type":"choix","options":[{"id":"a","texte":"Éclairer avec une lumière rouge, de longueur d’onde plus grande, pour réduire la diffraction"},{"id":"b","texte":"Changer l’oculaire pour un modèle de focale plus courte, ce qui suffit à séparer tout détail"},{"id":"c","texte":"Utiliser une lumière de longueur d’onde plus courte et un objectif d’ouverture numérique plus grande"},{"id":"d","texte":"Augmenter seulement le grossissement de l’oculaire, sans rien changer d’autre au microscope"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’**objectif** est tout près de l’échantillon ; l’oculaire, près de l’œil, agit comme une loupe sur l’image qu’il a formée."},{"cle":{"type":"nombre","valeur":12.5,"tolerance":0.1},"affichage":"12,5","explication":"G_c = 0,25 ÷ 0,020 = **12,5**."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"250 ÷ 12,5 = 20 : c’est l’**objectif B** (× 20)."},{"cle":{"type":"choix","ids":["c"]},"explication":"La résolution est limitée par la diffraction : elle s’améliore avec un **λ plus court** et une **ouverture numérique plus grande**. Grossir davantage ne crée pas de détail."}]$ex$::jsonb),
  ('82b4de1b-b61d-5add-8100-816c07b8661f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Séparer deux étoiles avec une lunette","competence":"modeliser","situation":"Une lunette astronomique réglée à l’infini sert à séparer deux étoiles très proches, observées à la longueur d’onde 550 nm. L’œil nu ne sépare pas deux points vus sous un angle inférieur à 3 × 10⁻⁴ rad. On compare ensuite la lunette à un télescope de Newton.","documents":[{"id":"lunette","type":"tableau","titre":"La lunette","colonnes":["Grandeur","Valeur"],"enteteLignes":true,"lignes":[["Focale de l’objectif f’₁","120 cm"],["Focale de l’oculaire f’₂","2,0 cm"],["Diamètre de l’objectif D","8,0 cm"]]},{"id":"newton","type":"schema","titre":"Télescope de Newton","largeur":320,"hauteur":210,"elements":[{"forme":"rect","x":40,"y":90,"l":200,"h":80},{"forme":"chemin","d":"M52 96 Q28 130 52 164","id":"z1","zone":true},{"forme":"ligne","de":[192,150],"a":[224,118],"id":"z2","zone":true},{"forme":"ellipse","cx":208,"cy":78,"rx":16,"ry":6,"id":"z3","zone":true},{"forme":"ligne","de":[300,105],"a":[245,105],"fleche":"fin"},{"forme":"ligne","de":[300,158],"a":[245,158],"fleche":"fin"},{"forme":"texte","x":270,"y":80,"texte":"Lumière","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Calcule le grossissement de la lunette. On donne G = f’₁ ÷ f’₂.","aide":"Garde les deux focales dans la même unité.","type":"nombre"},{"enonce":"La lunette est afocale : les foyers de l’objectif et de l’oculaire sont confondus. Quelle distance sépare les deux lentilles, en centimètres ?","aide":"La distance est la somme des deux focales.","type":"nombre","unite":"cm"},{"enonce":"Calcule la plus petite séparation angulaire que l’objectif permet de distinguer, en microradians (1 µrad = 10⁻⁶ rad). On donne θ_min ≈ 1,22 × λ ÷ D.","aide":"Convertis D = 8,0 cm en mètres : 0,080 m.","type":"nombre","unite":"µrad"},{"enonce":"Quel grossissement minimal faut-il pour que l’œil sépare deux étoiles écartées de θ_min ? (Angle minimal de l’œil : 3 × 10⁻⁴ rad.)","aide":"Divise 3 × 10⁻⁴ par θ_min, dans la même unité.","type":"nombre"},{"enonce":"Touche le miroir concave qui joue le rôle de l’objectif de la lunette.","aide":"Il est au fond du tube, à l’opposé de l’entrée de la lumière.","type":"zone","document":"newton","multiple":false}]}$ex$::jsonb,
