   $ex${"titre":"Du capteur au nombre","competence":"observer-schema","situation":"Un thermomètre électronique suit la chaîne d’information ci-dessous. Son capteur fournit 10 mV par degré Celsius. Le convertisseur analogique-numérique (CAN) a 12 bits et une plage de 0 à 4,096 V. Le conditionneur et le filtre ne changent pas la valeur de la tension.","documents":[{"id":"chaine","type":"chaine","titre":"Chaîne d’information","disposition":"ligne","noeuds":[{"id":"z1","texte":"Capteur"},{"id":"z2","texte":"Conditionneur"},{"id":"z3","texte":"Filtre"},{"id":"z4","texte":"CAN"},{"id":"z5","texte":"Micro-contrôleur"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche le bloc qui transforme la tension analogique en un nombre que le micro-contrôleur peut lire.","aide":"Le signal devient numérique à cet endroit de la chaîne.","type":"zone","document":"chaine","multiple":false},{"enonce":"Quelle est la résolution (le quantum) du CAN, en millivolts ? On donne q = plage de tension ÷ 2ⁿ.","aide":"Ici n = 12, donc 2¹² = 4 096.","type":"nombre","unite":"mV"},{"enonce":"Le CAN affiche le nombre 235. Quelle tension cela représente-t-il, en millivolts ?","aide":"Chaque unité du nombre vaut un quantum.","type":"nombre","unite":"mV"},{"enonce":"Quelle température mesure le thermomètre, en degrés Celsius ?","aide":"Le capteur donne 10 mV par degré : divise la tension par 10 mV.","type":"nombre","unite":"°C"}]}$ex$::jsonb,
