  ('2b79d30e-d725-5262-b5e6-b685eb86f0f5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Filtrer le bruit, guider la lumière","competence":"lire-graphique","situation":"Un capteur de pression délivre un signal utile lent, pollué par un bruit de fréquence 10 kHz. On le filtre avec un filtre passe-bas dont on a relevé l’atténuation. Le signal est ensuite envoyé dans une fibre optique à saut d’indice.","documents":[{"id":"filtre","type":"graphique","forme":"courbe","titre":"Atténuation du filtre","categories":["0,1","0,5","1","2","5","10"],"series":[{"nom":"Atténuation","valeurs":[0,1,3,7,14.1,20]}],"axeY":{"titre":"Atténuation","unite":"dB","min":0,"max":25,"pas":5},"axeX":{"titre":"Fréquence (kHz)"},"valeurs":false,"source":"Mesures idéalisées"},{"id":"fibre","type":"tableau","titre":"La fibre optique","colonnes":["Partie","Indice de réfraction"],"enteteLignes":true,"lignes":[["Cœur n₁","1,48"],["Gaine n₂","1,46"]]}],"questions":[{"enonce":"Touche la fréquence de coupure du filtre, celle où l’atténuation atteint 3 dB.","aide":"La fréquence de coupure correspond à une chute de 3 dB par rapport au gain maximal.","type":"zone","document":"filtre","multiple":false},{"enonce":"Le bruit de 10 kHz a une amplitude de 50 mV avant le filtre. Quelle amplitude a-t-il après, en millivolts ? On donne G = 20 × log (U_sortie ÷ U_entrée).","aide":"Lis l’atténuation à 10 kHz : le gain est −20 dB, donc U_s ÷ U_e = 10⁻¹.","type":"nombre","unite":"mV"},{"enonce":"Calcule l’ouverture numérique de la fibre. On donne ON = √(n₁² − n₂²).","aide":"n₁² − n₂² = 2,1904 − 2,1316.","type":"nombre"},{"enonce":"Déduis-en l’angle d’acceptance maximal θ_max de la fibre, en degrés. On donne sin θ_max = ON.","aide":"Utilise sin⁻¹ (0,2425) sur la calculatrice en degrés.","type":"nombre","unite":"°"}]}$ex$::jsonb,
