  ('2b79d30e-d725-5262-b5e6-b685eb86f0f5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Réguler un chauffe-eau","competence":"analyser-document","situation":"Un chauffe-eau doit passer de 20 °C à une consigne de 60 °C. On compare une correction proportionnelle (P) et une correction proportionnelle intégrale (PI). Une vanne de gaz est ensuite ouverte par un moteur pas à pas dont le tableau donne les caractéristiques.","documents":[{"id":"courbe-reponse","type":"graphique","forme":"courbe","titre":"Température de l’eau après l’échelon de consigne","categories":["0","5","10","15","20","25","30"],"series":[{"nom":"Correction P","valeurs":[20,38,48,53,55.5,56.7,57]},{"nom":"Correction PI","valeurs":[20,40,55,63,61,60.4,60]}],"axeY":{"titre":"Température","unite":"°C","min":0,"max":70,"pas":10},"axeX":{"titre":"Temps (min)"},"valeurs":false,"source":"Mesures idéalisées"},{"id":"moteur","type":"tableau","titre":"Moteur pas à pas de la vanne","colonnes":["Caractéristique","Valeur"],"enteteLignes":true,"lignes":[["Nombre de pas par tour","48"],["Tours pour ouvrir la vanne","6"]]}],"questions":[{"enonce":"Quel est l’écart statique de la correction P, en degrés Celsius ?","aide":"L’écart statique est la différence finale entre la consigne et la température.","type":"nombre","unite":"°C"},{"enonce":"Touche l’instant où la correction PI dépasse le plus la consigne.","aide":"Cherche le point le plus haut de la courbe de la correction PI.","type":"zone","document":"courbe-reponse","multiple":false},{"enonce":"Quel est le temps de réponse à 5 % de la correction PI, en minutes ? La variation totale est de 40 °C : la température doit rester à ± 5 % de cette variation autour de 60 °C.","aide":"5 % de 40 °C valent 2 °C : la température doit rester entre 58 °C et 62 °C.","type":"nombre","unite":"min"},{"enonce":"De quel angle tourne le moteur à chaque pas, en degrés ?","aide":"Un tour complet fait 360°.","type":"nombre","unite":"°"},{"enonce":"Combien d’impulsions faut-il envoyer au moteur pour ouvrir complètement la vanne ?","aide":"Multiplie le nombre de pas par tour par le nombre de tours.","type":"nombre"}]}$ex$::jsonb,
