  ('13559c26-0e01-500d-81c8-2da32170eefe'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Trois façons de chauffer une maison","competence":"lire-tableau","situation":"En hiver, la chaleur circule dans la maison de trois façons différentes, qu’on repère dans le premier tableau. On étudie ensuite un mur par lequel elle s’échappe. On donne R_th = e ÷ (λ × S) et Φ = (T_chaude − T_froide) ÷ R_th.","documents":[{"id":"situations","type":"tableau","titre":"Trois situations","colonnes":["Repère","Situation"],"enteteLignes":true,"lignes":[["A","Le manche métallique d’une casserole chauffe peu à peu"],["B","L’air circule au-dessus d’un radiateur"],["C","Le Soleil chauffe le visage à travers une vitre"]]},{"id":"mur","type":"tableau","titre":"Le mur","colonnes":["Grandeur","Valeur"],"enteteLignes":true,"lignes":[["Épaisseur e","0,20 m"],["Surface S","10 m²"],["Conductivité λ","1,0 W·m⁻¹·K⁻¹"],["Température intérieure","20 °C"],["Température extérieure","0 °C"]]}],"questions":[{"enonce":"Relie chaque situation à son mode de transfert thermique.","aide":"Demande-toi : la chaleur passe-t-elle de proche en proche, par un fluide en mouvement, ou par des ondes ?","type":"association","gauche":[{"id":"g0","texte":"Le manche de la casserole"},{"id":"g1","texte":"L’air au-dessus du radiateur"},{"id":"g2","texte":"Le Soleil sur le visage"}],"droite":[{"id":"d0","texte":"Convection"},{"id":"d1","texte":"Rayonnement"},{"id":"d2","texte":"Conduction"}]},{"enonce":"Touche la situation où le transfert n’a besoin d’aucun milieu matériel.","aide":"Un seul mode de transfert traverse le vide.","type":"zone","document":"situations","multiple":false},{"enonce":"Calcule la résistance thermique du mur, en K/W.","aide":"R_th = 0,20 ÷ (1,0 × 10).","type":"nombre","unite":"K/W"},{"enonce":"Calcule le flux thermique perdu à travers le mur, en watts.","aide":"L’écart de température est 20 − 0 = 20 K.","type":"nombre","unite":"W"}]}$ex$::jsonb,
