ultiple":false},{"enonce":"À quelle température apparaît la première bulle quand on chauffe ce mélange, en degrés Celsius ?","aide":"La première bulle se lit sur la courbe d’ébullition, celle du bas.","type":"nombre","unite":"°C"},{"enonce":"Comment est la première vapeur par rapport au liquide de départ ?","aide":"La vapeur est plus riche en constituant le plus volatil.","type":"choix","options":[{"id":"a","texte":"Faite uniquement de B, qui serait le premier des deux liquides à s’évaporer"},{"id":"b","texte":"Plus riche en A, le constituant le plus volatil, que le liquide de départ"},{"id":"c","texte":"Plus riche en B, parce que B a la température d’ébullition la plus élevée des deux"},{"id":"d","texte":"De même composition que le liquide de départ, avec x_A égal à 0,60 exactement"}],"multiple":false},{"enonce":"Touche le récipient qui recueille le distillat, riche en constituant le plus volatil.","aide":"Le distillat sort en tête de colonne, après le condenseur.","type":"zone","document":"colonne","multiple":false}]}$ex$::jsonb,
